package com.bank.draw;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class RandomizedSetDemo {

    private static final Logger log = Logger.getLogger(RandomizedSetDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RandomizedSet draw = new RandomizedSet();

        log.info(() -> "insert SAV2001 -> " + draw.insert("SAV2001"));   // true
        log.info(() -> "insert CUR3001 -> " + draw.insert("CUR3001"));   // true
        log.info(() -> "insert SAV2001 -> " + draw.insert("SAV2001"));   // false, already present
        log.info(() -> "insert SAV4002 -> " + draw.insert("SAV4002"));   // true

        log.info(() -> "random eligible account -> " + draw.getRandom());

        log.info(() -> "remove CUR3001 -> " + draw.remove("CUR3001"));   // true
        log.info(() -> "remove CUR3001 -> " + draw.remove("CUR3001"));   // false, gone
        log.info(() -> "random eligible account -> " + draw.getRandom());
    }
}

