class RandomizedSet {

    private static final Logger log = Logger.getLogger(RandomizedSet.class.getName());

    private final List<String> elements = new ArrayList<>();
    private final Map<String, Integer> indexOf = new HashMap<>();
    private final Random random = new Random();

    // O(1) average: insert if absent.
    boolean insert(String value) {
        if (indexOf.containsKey(value)) {
            return false;
        }
        indexOf.put(value, elements.size());
        elements.add(value);
        return true;
    }

    // O(1) average: remove by swapping with the last element.
    boolean remove(String value) {
        Integer idx = indexOf.get(value);
        if (idx == null) {
            return false;
        }
        int lastIndex = elements.size() - 1;
        String lastValue = elements.get(lastIndex);
        // Move the last element into the vacated slot.
        elements.set(idx, lastValue);
        indexOf.put(lastValue, idx);
        // Trim the last slot and drop the removed key.
        elements.remove(lastIndex);
        indexOf.remove(value);
        log.fine(() -> "removed " + value + ", moved " + lastValue + " into slot " + idx);
        return true;
    }

    // O(1): uniformly random element.
    String getRandom() {
        if (elements.isEmpty()) {
            throw new IllegalStateException("set is empty");
        }
        int pick = random.nextInt(elements.size());
        return elements.get(pick);
    }
}

